class Solution {
    public long bestPair(int[][] posts, int k) {
        long best = Long.MIN_VALUE;
        for (int j = 0; j < posts.length; j++) {
            for (int i = 0; i < j; i++) {
                if (posts[j][0] - posts[i][0] <= k) {
                    long value = (long) posts[i][1] + posts[j][1] + posts[j][0] - posts[i][0];
                    best = Math.max(best, value);
                }
            }
        }
        return best;
    }
}

