class Solution {
    public long bestPair(int[][] posts, int k) {
        int n = posts.length;
        int[] dq = new int[n];
        int head = 0, tail = 0;
        long best = Long.MIN_VALUE;
        for (int j = 0; j < n; j++) {
            int x = posts[j][0], y = posts[j][1];
            while (tail > head && x - posts[dq[head]][0] > k) head++;
            if (tail > head) {
                int i = dq[head];
                best = Math.max(best, (long) y + x + posts[i][1] - posts[i][0]);
            }
            while (tail > head && posts[dq[tail - 1]][1] - posts[dq[tail - 1]][0] <= y - x) tail--;
            dq[tail++] = j;
        }
        return best;
    }
}

