class Solution {
public:
    long long bestPair(vector<vector<int>>& posts, int k) {
        deque<int> dq;
        long long best = LLONG_MIN;
        for (int j = 0; j < (int) posts.size(); j++) {
            int x = posts[j][0], y = posts[j][1];
            while (!dq.empty() && x - posts[dq.front()][0] > k) dq.pop_front();
            if (!dq.empty()) {
                int i = dq.front();
                best = max(best, (long long) y + x + posts[i][1] - posts[i][0]);
            }
            while (!dq.empty() && posts[dq.back()][1] - posts[dq.back()][0] <= y - x) dq.pop_back();
            dq.push_back(j);
        }
        return best;
    }
};

